"""Behavioral tests for accepted registry publication and adoption rules.

These tests mirror the accepted contract in docs/contract.md: publication
only adds availability, while adoption changes one known use to one already
published version. Retry limits are modeled here as adjacent per-use state to
prove the registry operations do not centralize or mutate local configuration.
"""

import unittest

from src.registry import adopt, publish


class RegistryOperationTests(unittest.TestCase):
    """Contract tests for the small in-memory registry surface."""

    def test_publication_preserves_existing_usages_and_local_retry_limits(self):
        """Publishing a version must not roll any existing use forward."""
        versions = {"v1"}
        usages = {"tile:summary": "v1", "job:nightly": "v1"}
        retry_limits = {"tile:summary": 1, "job:nightly": 5}

        publish(versions, "v2")

        self.assertEqual({"v1", "v2"}, versions)
        self.assertEqual({"tile:summary": "v1", "job:nightly": "v1"}, usages)
        self.assertEqual({"tile:summary": 1, "job:nightly": 5}, retry_limits)

    def test_explicit_adoption_changes_only_target_usage(self):
        """Tile-like and job-like uses share adoption semantics."""
        versions = {"v1", "v2"}
        usages = {"tile:summary": "v1", "job:nightly": "v1"}
        retry_limits = {"tile:summary": 1, "job:nightly": 5}

        adopt(usages, "tile:summary", "v2", versions)

        self.assertEqual({"tile:summary": "v2", "job:nightly": "v1"}, usages)
        self.assertEqual({"v1", "v2"}, versions)
        self.assertEqual({"tile:summary": 1, "job:nightly": 5}, retry_limits)

    def test_invalid_adoption_rejects_unknown_usage_without_mutation(self):
        """Adoption must not create a use as a side effect of validation."""
        versions = {"v1"}
        usages = {"tile:summary": "v1"}

        with self.assertRaises(ValueError):
            adopt(usages, "job:nightly", "v1", versions)

        self.assertEqual({"tile:summary": "v1"}, usages)
        self.assertEqual({"v1"}, versions)

    def test_invalid_adoption_rejects_unpublished_version_without_mutation(self):
        """Adoption must not publish a version as a side effect of validation."""
        versions = {"v1"}
        usages = {"tile:summary": "v1"}

        with self.assertRaises(ValueError):
            adopt(usages, "tile:summary", "v2", versions)

        self.assertEqual({"tile:summary": "v1"}, usages)
        self.assertEqual({"v1"}, versions)


if __name__ == "__main__":
    unittest.main()
